INSERT INTO `app_template` (`id`, `template`, `path`, `active`, `app_id`, `created_at`, `updated_at`, `hash`) VALUES
(UNHEX('019BBB6B52047139888A57CAB9236C08'),	'<div class=\"spatial-canvas-spinner position-absolute top-50 start-50 flex justify-content-center align-items-center\" style=\"--bs-bg-opacity: .8;\">\n    <div class=\"spinner-border\" role=\"status\">\n        <span class=\"visually-hidden\">Loading...</span>\n    </div>\n</div>\n',	'storefront/element/cms-element-image-gallery-loading-spinner.html.twig',	1,	UNHEX('019BBB6B4D3F7373A6848623014E0859'),	'2026-01-14 07:32:11.397',	'2026-01-14 07:32:11.919',	'd6179db9d979e71c24c5958347a142bc'),
(UNHEX('019BBB6B52047139888A57CAB9C01538'),	'{% sw_extends \'@SwagCommerical/storefront/element/cms-element-spatial-viewer.html.twig\' %}\n\n{% block spatial_cms_viewer_element_canvas_loading_spinner %}\n\n    {% if element.data.hasExtension(\'preview\') %}\n        {% set preview = element.data.getExtension(\'preview\') %}\n\n        {% set attributes = {\n            class: attributes.class ~ \' position-absolute top-50 start-50 translate-middle h-100 opacity-25\',\n            alt: preview.translated.alt,\n            tabindex: \"0\",\n            \'data-object-fit\' : \"contain\",\n            itemprop : \"image\",\n            fetchpriority : \"high\",\n        } %}\n\n        <div class=\"spatial-canvas-spinner position-absolute overflow-hidden w-100 h-100\" >\n\n            {% sw_thumbnails \'gallery-slider-image-thumbnails\' with {\n                media: preview,\n                attributes: attributes,\n                load: true,\n                loadOriginalImage: false,\n                autoColumnSizes: false\n            } %}\n\n            {% sw_include \'@SwagPreviewGenerator/storefront/element/cms-element-image-gallery-loading-spinner.html.twig\' %}\n        </div>\n    {% else %}\n        {{ parent() }}\n    {% endif %}\n{% endblock %}\n',	'storefront/element/cms-element-spatial-viewer.html.twig',	1,	UNHEX('019BBB6B4D3F7373A6848623014E0859'),	'2026-01-14 07:32:11.397',	'2026-01-14 07:32:11.919',	'74d2ba61f15b39d2afd924b6b4929ef0'),
(UNHEX('019BBB6B52047139888A57CABA4FAF7E'),	'{% sw_extends \'@Storefront/storefront/element/cms-element-image-gallery.html.twig\' %}\n\n{# preview normal menu #}\n{% block element_image_gallery_inner_thumbnails_item_inner_spatial %}\n\n    {% if image.hasExtension(\'preview\') %}\n        {% set preview = image.getExtension(\'preview\') %}\n\n        {% set attributes = attributes|merge({\n            alt: (preview.translated.alt ?: fallbackImageTitle)\n        }) %}\n\n        {% if isProduct %}\n            {% set attributes = attributes|merge({ itemprop: \'image\' }) %}\n        {% endif %}\n\n        {% sw_thumbnails \'gallery-slider-thumbnails-image-thumbnails\' with {\n            media: preview,\n            sizes: {\n                default: \'200px\'\n            },\n            attributes: attributes\n        } %}\n        <span class=\"badge bg-secondary m-1 position-absolute bottom-0 end-0\">3D</span>\n    {% else %}\n        {{ parent() }}\n    {% endif %}\n{% endblock %}\n\n{# preview menu big #}\n{% block element_image_gallery_inner_zoom_modal_thumbnails_item_inner_spatial %}\n\n    {% if image.hasExtension(\'preview\') %}\n        {% set preview = image.getExtension(\'preview\') %}\n\n        {% set attributes = attributes|merge({\n             class: attributes.class ~ \' js-load-img\',\n             alt: (preview.translated.alt ?: fallbackImageTitle)\n         }) %}\n\n         {% sw_thumbnails \'gallery-slider-thumbnails-image-thumbnails\' with {\n             media: preview,\n             sizes: {\n                 default: \'200px\'\n             },\n             attributes: attributes,\n             load: false\n         } %}\n         <span class=\"badge bg-secondary m-1 position-absolute bottom-0 end-0\">3D</span>\n     {% else %}\n         {{ parent() }}\n     {% endif %}\n {% endblock %}\n\n{# loading background normal #}\n{% block element_image_gallery_inner_item_spatial_loader %}\n\n    {% if image.hasExtension(\'preview\') %}\n        <span class=\"badge bg-secondary m-3 position-absolute top-0 end-0 d-md-none\">3D</span>\n\n        {% set preview = image.getExtension(\'preview\') %}\n\n        {% set attributes = attributes|merge({\n            class: attributes.class ~ \' magnifier-image js-magnifier-image opacity-25\',\n            alt: (preview.translated.alt ?: fallbackImageTitle),\n            \'data-full-image\': preview.url,\n            \'tabindex\': \'0\'\n        }) %}\n\n        {% if displayMode == \'cover\' or displayMode == \'contain\' %}\n            {% set attributes = attributes|merge({ \'data-object-fit\': displayMode }) %}\n        {% endif %}\n\n        {% if isProduct %}\n            {% set attributes = attributes|merge({ itemprop: \'image\' }) %}\n        {% endif %}\n\n        {% if loop.first %}\n            {% set attributes = attributes|merge({ fetchpriority: \'high\' }) %}\n        {% endif %}\n\n        {% sw_thumbnails \'gallery-slider-image-thumbnails\' with {\n            media: preview,\n            attributes: attributes\n        } %}\n\n        {% sw_include \'@SwagPreviewGenerator/storefront/element/cms-element-image-gallery-loading-spinner.html.twig\' %}\n    {% else %}\n        {{ parent() }}\n    {% endif %}\n{% endblock %}\n\n{# loading background big #}\n{% block element_image_gallery_inner_zoom_modal_slider_item_image_spatial %}\n\n    {% if image.hasExtension(\'preview\') %}\n        {% set preview = image.getExtension(\'preview\') %}\n\n        {% set attributes = attributes|merge({\n            class: attributes.class ~ \' js-image-zoom-element js-load-img opacity-25\',\n            alt: (preview.translated.alt ?: fallbackImageTitle),\n            tabindex: \"0\"\n        }) %}\n\n        {% sw_thumbnails \'gallery-slider-image-thumbnails\' with {\n            media: preview,\n            attributes: attributes,\n            load: false,\n            loadOriginalImage: true,\n            autoColumnSizes: false\n        } %}\n\n        {% sw_include \'@SwagPreviewGenerator/storefront/element/cms-element-image-gallery-loading-spinner.html.twig\' %}\n    {% else %}\n        {{ parent() }}\n    {% endif %}\n{% endblock %}\n\n{% block element_image_gallery_inner_zoom_modal_slider_item_zoom_container_spatial_loader %}\n    {% if image.hasExtension(\'preview\') %}\n        {% sw_include \'@SwagPreviewGenerator/storefront/element/cms-element-image-gallery-loading-spinner.html.twig\' %}\n    {% else %}\n        {{ parent() }}\n    {% endif %}\n{% endblock %}\n\n{# loading background zoom #}\n{% block element_image_gallery_inner_single_spatial_loader %}\n\n    {% if image.hasExtension(\'preview\') %}\n        <span class=\"badge bg-secondary m-3 position-absolute top-0 end-0 d-md-none\">3D</span>\n\n        {% set preview = image.getExtension(\'preview\') %}\n\n        {% set attributes = attributes|merge({\n            class: attributes.class ~ \' magnifier-image js-magnifier-image opacity-25\',\n            alt: (image.translated.alt ?: fallbackImageTitle),\n            \'tabindex\': \'0\'\n        }) %}\n\n        {% sw_thumbnails \'gallery-slider-thumbnails-image-thumbnails\' with {\n            media: preview,\n            attributes: attributes,\n        } %}\n\n        {% sw_include \'@SwagPreviewGenerator/storefront/element/cms-element-image-gallery-loading-spinner.html.twig\' %}\n    {% else %}\n        {{ parent() }}\n    {% endif %}\n{% endblock %}\n',	'storefront/element/cms-element-image-gallery.html.twig',	1,	UNHEX('019BBB6B4D3F7373A6848623014E0859'),	'2026-01-14 07:32:11.397',	'2026-01-14 07:32:11.919',	'8729e576f0c328f226a63bfc97c20575');

