(UNHEX('019BBB6A64C771FD8337CCB89AAE19BB'),	UNHEX('019BBB6ADAF07027AAE9AFD1663F88B7'),	'Default email footer',	'Default email footer derived from basic information',	NULL,	NULL,	'<div style=\"font-family:arial; font-size:12px;\">\n    Address:<br>\n    {{ config(\'core.basicInformation.address\')|raw }}\n    <br>\n    Bank account:<br>\n    {{ config(\'core.basicInformation.bankAccount\')|raw }}\n</div>\n',	'\n\n        Address:\n        {{ config(\'core.basicInformation.address\')|striptags(\'<br>\')|replace({\"<br>\":\"\\n\"}) }}\n\n        Bank account:\n        {{ config(\'core.basicInformation.bankAccount\')|striptags(\'<br>\')|replace({\"<br>\":\"\\n\"}) }}\n',	'2026-01-14 07:31:10.669',	NULL),
(UNHEX('019BBB6A64C771FD8337CCB89AAE19BB'),	UNHEX('2FBB5FE2E29A4D70AA5854CE7CE3E20B'),	'Standard-E-Mail-Fußzeile',	'Standard-E-Mail-Fußzeile basierend auf den Stammdaten',	NULL,	NULL,	'<div style=\"font-family:arial; font-size:12px;\">\n    Adresse:<br>\n    {{ config(\'core.basicInformation.address\')|raw }}\n    <br>\n    Bankverbindung:<br>\n    {{ config(\'core.basicInformation.bankAccount\')|raw }}\n</div>\n',	'\n\n        Adresse:\n        {{ config(\'core.basicInformation.address\')|striptags(\'<br>\')|replace({\"<br>\":\"\\n\"}) }}\n\n        Bankverbindung:\n        {{ config(\'core.basicInformation.bankAccount\')|striptags(\'<br>\')|replace({\"<br>\":\"\\n\"}) }}\n',	'2026-01-14 07:31:10.671',	NULL);

