DROP TABLE IF EXISTS `mail_template_media`;
CREATE TABLE `mail_template_media` (
  `id` binary(16) NOT NULL,
  `mail_template_id` binary(16) NOT NULL,
  `language_id` binary(16) DEFAULT NULL,
  `media_id` binary(16) NOT NULL,
  `position` int NOT NULL DEFAULT '1',
  PRIMARY KEY (`id`),
  KEY `fk.mail_template_media.mail_template_id` (`mail_template_id`),
  KEY `fk.mail_template_media.media_id` (`media_id`),
  KEY `fk.mail_template_media.language_id` (`language_id`),
  CONSTRAINT `fk.mail_template_media.language_id` FOREIGN KEY (`language_id`) REFERENCES `language` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk.mail_template_media.mail_template_id` FOREIGN KEY (`mail_template_id`) REFERENCES `mail_template` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk.mail_template_media.media_id` FOREIGN KEY (`media_id`) REFERENCES `media` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `mail_template_translation`;
CREATE TABLE `mail_template_translation` (
  `mail_template_id` binary(16) NOT NULL,
  `language_id` binary(16) NOT NULL,
  `sender_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `subject` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `description` longtext COLLATE utf8mb4_unicode_ci,
  `content_html` longtext COLLATE utf8mb4_unicode_ci,
  `content_plain` longtext COLLATE utf8mb4_unicode_ci,
  `custom_fields` json DEFAULT NULL,
  `created_at` datetime(3) NOT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  PRIMARY KEY (`mail_template_id`,`language_id`),
  KEY `fk.mail_template_translation.language_id` (`language_id`),
  CONSTRAINT `fk.mail_template_translation.language_id` FOREIGN KEY (`language_id`) REFERENCES `language` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk.mail_template_translation.mail_template_id` FOREIGN KEY (`mail_template_id`) REFERENCES `mail_template` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `json.mail_template_translation.custom_fields` CHECK (json_valid(`custom_fields`))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `mail_template_translation` (`mail_template_id`, `language_id`, `sender_name`, `subject`, `description`, `content_html`, `content_plain`, `custom_fields`, `created_at`, `updated_at`) VALUES
(UNHEX('019BBB6A0A3372AE957206ED654301C9'),	UNHEX('019BBB6ADAF07027AAE9AFD1663F88B7'),	'{{ salesChannel.translated.name }}',	'Newsletter',	'',	'<h3>Hello {{ newsletterRecipient.firstName }} {{ newsletterRecipient.lastName }}</h3>\n                <p>Thank you for your interest in our newsletter!</p>\n                <p>In order to prevent misuse of your email address, we have sent you this confirmation email. Confirm that you wish to receive the newsletter regularly by clicking <a href=\"{{ url }}\">here</a>.</p>\n                <p>If you have not subscribed to the newsletter, please ignore this email.</p>\n        ',	'Hello {{ newsletterRecipient.firstName }} {{ newsletterRecipient.lastName }}\n\n                Thank you for your interest in our newsletter!\n\n                In order to prevent misuse of your email address, we have sent you this confirmation email. Confirm that you wish to receive the newsletter regularly by clicking on the link: {{ url }}\n\n                If you have not subscribed to the newsletter, please ignore this email.\n        ',	NULL,	'2026-01-14 07:30:47.478',	NULL),
(UNHEX('019BBB6A0A3372AE957206ED654301C9'),	UNHEX('2FBB5FE2E29A4D70AA5854CE7CE3E20B'),	'{{ salesChannel.translated.name }}',	'Newsletter',	'',	'<h3>Hallo {{ newsletterRecipient.firstName }} {{ newsletterRecipient.lastName }}</h3>\n                <p>Schön, dass Sie sich für unseren Newsletter interessieren!</p>\n                <p>Um einem Missbrauch Ihrer E-Mail-Adresse vorzubeugen, haben wir Ihnen diese Bestätigungsmail gesendet. Bestätigen Sie, dass Sie den Newsletter regelmäßig erhalten wollen, indem Sie <a href=\"{{ url }}\">hier</a> klicken.</p>\n                <p>Sollten Sie den Newsletter nicht angefordert haben, ignorieren Sie diese E-Mail.</p>\n        ',	'Hallo {{ newsletterRecipient.firstName }} {{ newsletterRecipient.lastName }}\n\n                Schön, dass Sie sich für unseren Newsletter interessieren!\n\n                Um einem Missbrauch Ihrer E-Mail-Adresse vorzubeugen, haben wir Ihnen diese Bestätigungsmail gesendet. Bestätigen Sie, dass Sie den Newsletter regelmäßig erhalten wollen, indem Sie auf den folgenden Link klicken: {{ url }}\n\n                Sollten Sie den Newsletter nicht angefordert haben, ignorieren Sie diese E-Mail.\n        ',	NULL,	'2026-01-14 07:30:47.482',	NULL),
(UNHEX('019BBB6A0A3473A78AC4F44B5E49A07A'),	UNHEX('019BBB6ADAF07027AAE9AFD1663F88B7'),	'{{ salesChannel.translated.name }}',	'Register',	'',	'<h3>Hello {{ newsletterRecipient.firstName }} {{ newsletterRecipient.lastName }}</h3>\n                <p>thank you very much for your registration.</p>\n                <p>You have successfully subscribed to our newsletter.</p>\n        ',	'Hello {{ newsletterRecipient.firstName }} {{ newsletterRecipient.lastName }}\n\n                thank you very much for your registration.\n\n                You have successfully subscribed to our newsletter.\n        ',	NULL,	'2026-01-14 07:30:47.485',	NULL),
(UNHEX('019BBB6A0A3473A78AC4F44B5E49A07A'),	UNHEX('2FBB5FE2E29A4D70AA5854CE7CE3E20B'),	'{{ salesChannel.translated.name }}',	'Register',	'',	'<h3>Hallo {{ newsletterRecipient.firstName }} {{ newsletterRecipient.lastName }}</h3>\n                <p>vielen Dank für Ihre Anmeldung.</p>\n                <p>Sie haben sich erfolgreich zu unserem Newsletter angemeldet.</p>\n        ',	'Hallo {{ newsletterRecipient.firstName }} {{ newsletterRecipient.lastName }}\n\n                vielen Dank für Ihre Anmeldung.\n\n                Sie haben sich erfolgreich zu unserem Newsletter angemeldet.\n        ',	NULL,	'2026-01-14 07:30:47.487',	NULL),
(UNHEX('019BBB6A0A83706BA8C8BD1B204931CD'),	UNHEX('019BBB6ADAF07027AAE9AFD1663F88B7'),	'{{ salesChannel.name }}',	'Order confirmation',	'',	'<div style=\"font-family:arial; font-size:12px;\">\n\n    {% set currencyIsoCode = order.currency.isoCode %}\n    {% if order.orderCustomer.salutation %}{{ order.orderCustomer.salutation.translated.letterName ~ \' \' }}{% endif %}{{ order.orderCustomer.firstName }} {{ order.orderCustomer.lastName }},<br>\n    <br>\n    We have received your order from {{ order.orderDateTime|format_datetime(\'medium\', \'short\', locale=\'en-GB\') }}.<br>\n    <br>\n    Order number: {{ order.orderNumber }}<br>\n    <br>\n    As soon as your payment has been made, you will receive a separate notification and your order will be processed.<br>\n    <br>\n    You may check the current status of your order with this link: {{ rawUrl(\'frontend.account.order.single.page\', { \'deepLinkCode\': order.deepLinkCode }, salesChannel.domains|first.url) }}<br>\n    You may use this link to edit your order, change the payment method or make additional payments.<br>\n    <br>\n    <strong>Information on your order:</strong><br>\n    <br>\n\n    <table border=\"0\" style=\"font-family:Arial, Helvetica, sans-serif; font-size:12px;\">\n        <tr>\n            <td bgcolor=\"#F7F7F2\" style=\"border-bottom:1px solid #cccccc;\"><strong>Prod. no.</strong></td>\n            <td bgcolor=\"#F7F7F2\" style=\"border-bottom:1px solid #cccccc;\"><strong>Product image</strong></td>\n            <td bgcolor=\"#F7F7F2\" style=\"border-bottom:1px solid #cccccc;\"><strong>Description</strong></td>\n            <td bgcolor=\"#F7F7F2\" style=\"border-bottom:1px solid #cccccc;\"><strong>Quantities</strong></td>\n            <td bgcolor=\"#F7F7F2\" style=\"border-bottom:1px solid #cccccc;\"><strong>Price</strong></td>\n            <td bgcolor=\"#F7F7F2\" style=\"border-bottom:1px solid #cccccc;\"><strong>Total</strong></td>\n        </tr>\n\n        {% for lineItem in order.nestedLineItems %}\n            {% set nestingLevel = 0 %}\n            {% set nestedItem = lineItem %}\n            {% block lineItem %}\n                <tr>\n                    <td>{% if nestedItem.payload.productNumber is defined %}{{ nestedItem.payload.productNumber|u.wordwrap(80) }}{% endif %}</td>\n                    <td>{% if nestedItem.cover is defined and nestedItem.cover is not null %}<img src=\"{{ nestedItem.cover.url }}\" alt=\"\" width=\"75\" height=\"auto\"/>{% endif %}</td>\n                    <td>\n                        {% if nestingLevel > 0 %}\n                            {% for i in 1..nestingLevel %}\n                                <span style=\"position: relative;\">\n                            <span style=\"display: inline-block;\n                                position: absolute;\n                                width: 6px;\n                                height: 20px;\n                                top: 0;\n                                border-left:  2px solid rgba(0, 0, 0, 0.15);\n                                margin-left: {{ i * 10 }}px;\"></span>\n                        </span>\n                            {% endfor %}\n                        {% endif %}\n\n                        <div{% if nestingLevel > 0 %} style=\"padding-left: {{ (nestingLevel + 1) * 10 }}px\"{% endif %}>\n                            {{ nestedItem.label|u.wordwrap(80) }}\n                        </div>\n\n                        {% if nestedItem.payload.options is defined and nestedItem.payload.options|length >= 1 %}\n                            <div>\n                                {% for option in nestedItem.payload.options %}\n                                    {{ option.group }}: {{ option.option }}\n                                    {% if nestedItem.payload.options|last != option %}\n                                        {{ \" | \" }}\n                                    {% endif %}\n                                {% endfor %}\n                            </div>\n                        {% endif %}\n\n                        {% if nestedItem.payload.features is defined and nestedItem.payload.features|length >= 1 %}\n                            {% set referencePriceFeatures = nestedItem.payload.features|filter(feature => feature.type == \'referencePrice\') %}\n                            {% if referencePriceFeatures|length >= 1 %}\n                                {% set referencePriceFeature = referencePriceFeatures|first %}\n                                <div>\n                                    {{ referencePriceFeature.value.purchaseUnit }} {{ referencePriceFeature.value.unitName }}\n                                    ({{ referencePriceFeature.value.price|currency(currencyIsoCode) }} per {{ referencePriceFeature.value.referenceUnit }} {{ referencePriceFeature.value.unitName }})\n                                </div>\n                            {% endif %}\n                        {% endif %}\n                    </td>\n                    <td style=\"text-align: center\">{{ nestedItem.quantity }}</td>\n                    <td>{{ nestedItem.unitPrice|currency(currencyIsoCode) }}</td>\n                    <td>{{ nestedItem.totalPrice|currency(currencyIsoCode) }}</td>\n                </tr>\n\n                {% if nestedItem.children.count > 0 %}\n                    {% set nestingLevel = nestingLevel + 1 %}\n                    {% for lineItem in nestedItem.children %}\n                        {% set nestedItem = lineItem %}\n                        {{ block(\'lineItem\') }}\n                    {% endfor %}\n                {% endif %}\n            {% endblock %}\n        {% endfor %}\n    </table>\n\n    {% set delivery = order.deliveries.first %}\n\n    {% set displayRounded = order.totalRounding.interval != 0.01 or order.totalRounding.decimals != order.itemRounding.decimals %}\n    {% set decimals = order.totalRounding.decimals %}\n    {% set total = order.price.totalPrice %}\n    {% if displayRounded %}\n        {% set total = order.price.rawTotal %}\n        {% set decimals = order.itemRounding.decimals %}\n    {% endif %}\n    <p>\n        <br>\n        <br>\n        {% for shippingCost in order.deliveries %}\n            Shipping costs: {{ shippingCost.shippingCosts.totalPrice|currency(currencyIsoCode) }}<br>\n        {% endfor %}\n\n        Net total: {{ order.amountNet|currency(currencyIsoCode) }}<br>\n        {% for calculatedTax in order.price.calculatedTaxes %}\n            {% if order.taxStatus is same as(\'net\') %}plus{% else %}including{% endif %} {{ calculatedTax.taxRate }}% VAT. {{ calculatedTax.tax|currency(currencyIsoCode) }}<br>\n        {% endfor %}\n        {% if not displayRounded %}<strong>{% endif %}Total gross: {{ total|currency(currencyIsoCode,decimals=decimals) }}{% if not displayRounded %}</strong>{% endif %}<br>\n        {% if displayRounded %}\n            <strong>Rounded total gross: {{ order.price.totalPrice|currency(currencyIsoCode,decimals=order.totalRounding.decimals) }}</strong><br>\n        {% endif %}\n        <br>\n\n        {% if order.transactions is defined and order.transactions is not empty %}\n            <strong>Selected payment type:</strong> {{ order.transactions.first.paymentMethod.translated.name }}<br>\n            {{ order.transactions.first.paymentMethod.translated.description }}<br>\n            <br>\n        {% endif %}\n\n        {% if delivery %}\n            <strong>Selected shipping type:</strong> {{ delivery.shippingMethod.translated.name }}<br>\n            {{ delivery.shippingMethod.translated.description }}<br>\n            <br>\n        {% endif %}\n\n        {% set billingAddress = order.addresses.get(order.billingAddressId) %}\n        <strong>Billing address:</strong><br>\n        {{ billingAddress.company }}<br>\n        {{ billingAddress.firstName }} {{ billingAddress.lastName }}<br>\n        {{ billingAddress.street }} <br>\n        {{ billingAddress.zipcode }} {{ billingAddress.city }}<br>\n        {{ billingAddress.country.translated.name }}<br>\n        <br>\n\n        {% if delivery %}\n            <strong>Shipping address:</strong><br>\n            {{ delivery.shippingOrderAddress.company }}<br>\n            {{ delivery.shippingOrderAddress.firstName }} {{ delivery.shippingOrderAddress.lastName }}<br>\n            {{ delivery.shippingOrderAddress.street }} <br>\n            {{ delivery.shippingOrderAddress.zipcode}} {{ delivery.shippingOrderAddress.city }}<br>\n            {{ delivery.shippingOrderAddress.country.translated.name }}<br>\n            <br>\n        {% endif %}\n        {% if order.orderCustomer.vatIds %}\n            Your VAT-ID: {{ order.orderCustomer.vatIds|first }}\n            In case of a successful order and if you are based in one of the EU countries, you will receive your goods exempt from turnover tax.<br>\n        {% endif %}\n        <br>\n        You can check the current status of your order on our website under \"My account\" - \"My orders\" anytime: {{ rawUrl(\'frontend.account.order.single.page\', { \'deepLinkCode\': order.deepLinkCode }, salesChannel.domains|first.url) }}\n        <br>\n        If you have any questions, do not hesitate to contact us.\n        <br>\n        {% if a11yDocuments is defined and a11yDocuments is not empty %}\n            <br>\n            For better accessibility we also provide an HTML version of the documents here:<br><br>\n            <ul>\n                {% for a11y in a11yDocuments %}\n                    {% set documentLink = rawUrl(\n                        \'frontend.account.order.single.document.a11y\',\n                        {\n                            documentId: a11y.documentId,\n                            deepLinkCode: a11y.deepLinkCode,\n                            fileType: a11y.fileExtension,\n                        },\n                        salesChannel.domains|first.url\n                    )%}\n                    <li><a href=\"{{ documentLink }}\" target=\"_blank\">{{ documentLink }}</a></li>\n                {% endfor %}\n            </ul>\n            For data protection reasons the HTML version requires a login. <br><br>\n            In case of a guest order, you can use your email address and postal code of the billing address.<br>\n        {% endif %}\n    </p>\n    <br>\n</div>\n',	'{% set currencyIsoCode = order.currency.isoCode %}\n{% if order.orderCustomer.salutation %}{{ order.orderCustomer.salutation.translated.letterName ~ \' \' }}{% endif %}{{ order.orderCustomer.firstName }} {{ order.orderCustomer.lastName }},\n\nWe have received your order from {{ order.orderDateTime|format_datetime(\'medium\', \'short\', locale=\'en-GB\') }}.\n\nOrder number: {{ order.orderNumber }}\n\nAs soon as your payment has been made, you will receive a separate notification and your order will be processed.\n\nYou may check the current status of your order with this link: {{ rawUrl(\'frontend.account.order.single.page\', { \'deepLinkCode\': order.deepLinkCode }, salesChannel.domains|first.url) }}\nYou may use this link to edit your order, change the payment method or make additional payments.\n\nInformation on your order:\n\n{% for lineItem in order.lineItems %}\nPos. {{ loop.index }}\n---------------------\n{% if lineItem.payload.productNumber is defined %}\nProduct number {{ lineItem.payload.productNumber|u.wordwrap(80) }},\n{% endif %}\n{% if nestedItem.cover is defined and nestedItem.cover is not null %}\nImage {{ lineItem.cover.alt }},\n{% endif %}\nDescription {{ lineItem.label|u.wordwrap(80) }},\n{% if lineItem.payload.options is defined and lineItem.payload.options|length >= 1 %}\n{% for option in lineItem.payload.options %}\n{{ option.group }}: {{ option.option }}{{ \", \" }}\n{% endfor %}\n{% endif %}\n{% if lineItem.payload.features is defined and lineItem.payload.features|length >= 1 %}\n{% set referencePriceFeatures = lineItem.payload.features|filter(feature => feature.type == \'referencePrice\') %}\n{% if referencePriceFeatures|length >= 1 %}\n{% set referencePriceFeature = referencePriceFeatures|first %}\n{{ referencePriceFeature.value.purchaseUnit }} {{ referencePriceFeature.value.unitName }}({{ referencePriceFeature.value.price|currency(currencyIsoCode) }} per {{ referencePriceFeature.value.referenceUnit }} {{ referencePriceFeature.value.unitName }}),\n{% endif %}\n{% endif %}\nQuantity {{ lineItem.quantity }},\nPrice {{ lineItem.unitPrice|currency(currencyIsoCode) }},\nTotal {{ lineItem.totalPrice|currency(currencyIsoCode) }},\n\n{% endfor %}\n{% set delivery = order.deliveries.first %}\n{% set displayRounded = order.totalRounding.interval != 0.01 or order.totalRounding.decimals != order.itemRounding.decimals %}\n{% set decimals = order.totalRounding.decimals %}\n{% set total = order.price.totalPrice %}\n{% if displayRounded %}\n    {% set total = order.price.rawTotal %}\n    {% set decimals = order.itemRounding.decimals %}\n{% endif %}\n{% for shippingCost in order.deliveries %}\nShipping costs: {{ shippingCost.shippingCosts.totalPrice|currency(currencyIsoCode) }}\n{% endfor %}\nNet total: {{ order.amountNet|currency(currencyIsoCode) }}\n{% for calculatedTax in order.price.calculatedTaxes %}\n{% if order.taxStatus is same as(\'net\') %}plus{% else %}including{% endif %} {{ calculatedTax.taxRate }}% VAT. {{ calculatedTax.tax|currency(currencyIsoCode) }}\n{% endfor %}\nTotal gross: {{ total|currency(currencyIsoCode,decimals=decimals) }}\n{% if displayRounded %}\nRounded total gross: {{ order.price.totalPrice|currency(currencyIsoCode,decimals=order.totalRounding.decimals) }}\n{% endif %}\n\n{% if order.transactions is defined and order.transactions is not empty %}\nSelected payment type: {{ order.transactions.first.paymentMethod.translated.name }}\n{{ order.transactions.first.paymentMethod.translated.description }}\n{% endif %}\n\n{% if delivery %}\nSelected shipping type: {{ delivery.shippingMethod.translated.name }}\n{{ delivery.shippingMethod.translated.description }}\n{% endif %}\n{% set billingAddress = order.addresses.get(order.billingAddressId) %}\nBilling address:\n{{ billingAddress.company }}\n{{ billingAddress.firstName }} {{ billingAddress.lastName }}\n{{ billingAddress.street }}\n{{ billingAddress.zipcode }} {{ billingAddress.city }}\n{{ billingAddress.country.translated.name }}\n\n{% if delivery %}\nShipping address:\n{{ delivery.shippingOrderAddress.company }}\n{{ delivery.shippingOrderAddress.firstName }} {{ delivery.shippingOrderAddress.lastName }}\n{{ delivery.shippingOrderAddress.street }}\n{{ delivery.shippingOrderAddress.zipcode}} {{ delivery.shippingOrderAddress.city }}\n{{ delivery.shippingOrderAddress.country.translated.name }}\n{% endif %}\n\n{% if order.orderCustomer.vatIds %}\nYour VAT-ID: {{ order.orderCustomer.vatIds|first }}\nIn case of a successful order and if you are based in one of the EU countries, you will receive your goods exempt from turnover tax.\n\n{% endif %}\nYou can check the current status of your order on our website under \"My account\" - \"My orders\" anytime: {{ rawUrl(\'frontend.account.order.single.page\', { \'deepLinkCode\': order.deepLinkCode }, salesChannel.domains|first.url) }}\nIf you have any questions, do not hesitate to contact us.\n\n{% if a11yDocuments is defined and a11yDocuments is not empty %}\nFor better accessibility we also provide an HTML version of the documents here:\n\n{% for a11y in a11yDocuments %}\n{% set documentLink = rawUrl(\n    \'frontend.account.order.single.document.a11y\',\n    {\n        documentId: a11y.documentId,\n        \'deepLinkCode\': a11y.deepLinkCode,\n        fileType: a11y.fileExtension,\n    },\n    salesChannel.domains|first.url\n)%}\n- {{ documentLink }}\n{% endfor %}\n\nFor data protection reasons the HTML version requires a login.\nIn case of a guest order, you can use your email address and postal code of the billing address.\n{% endif %}\n',	NULL,	'2026-01-14 07:30:47.557',	NULL),
(UNHEX('019BBB6A0A83706BA8C8BD1B204931CD'),	UNHEX('2FBB5FE2E29A4D70AA5854CE7CE3E20B'),	'{{ salesChannel.name }}',	'Bestellbestätigung',	'',	'<div style=\"font-family:arial; font-size:12px;\">\n\n    {% set currencyIsoCode = order.currency.isoCode %}\n\n    Hallo {% if order.orderCustomer.salutation %}{{ order.orderCustomer.salutation.translated.letterName ~ \' \' }}{% endif %}{{ order.orderCustomer.firstName }} {{ order.orderCustomer.lastName }},<br>\n    <br>\n    Ihre Bestellung ist am {{ order.orderDateTime|format_datetime(\'medium\', \'short\', locale=\'de-DE\') }} bei uns eingegangen.<br>\n    <br>\n    Bestellnummer: {{ order.orderNumber }}<br>\n    <br>\n    Sobald ein Zahlungseingang erfolgt ist, erhalten Sie eine separate Benachrichtigung und Ihre Bestellung wird verarbeitet.<br>\n    <br>\n    Den aktuellen Status Ihrer Bestellung können Sie jederzeit über diesen Link abrufen: {{ rawUrl(\'frontend.account.order.single.page\', { \'deepLinkCode\': order.deepLinkCode }, salesChannel.domains|first.url) }}<br>\n    Über diesen Link können Sie auch die Bestellung bearbeiten, die Zahlungsart wechseln oder nachträglich eine Zahlung durchführen.<br>\n    <br>\n    <strong>Informationen zu Ihrer Bestellung:</strong><br>\n    <br>\n\n    <table border=\"0\" style=\"font-family:Arial, Helvetica, sans-serif; font-size:12px;\">\n        <tr>\n            <td bgcolor=\"#F7F7F2\" style=\"border-bottom:1px solid #cccccc;\"><strong>Produkt-Nr.</strong></td>\n            <td bgcolor=\"#F7F7F2\" style=\"border-bottom:1px solid #cccccc;\"><strong>Produktbild</strong></td>\n            <td bgcolor=\"#F7F7F2\" style=\"border-bottom:1px solid #cccccc;\"><strong>Bezeichnung</strong></td>\n            <td bgcolor=\"#F7F7F2\" style=\"border-bottom:1px solid #cccccc;\"><strong>Menge</strong></td>\n            <td bgcolor=\"#F7F7F2\" style=\"border-bottom:1px solid #cccccc;\"><strong>Preis</strong></td>\n            <td bgcolor=\"#F7F7F2\" style=\"border-bottom:1px solid #cccccc;\"><strong>Summe</strong></td>\n        </tr>\n\n        {% for lineItem in order.nestedLineItems %}\n            {% set nestingLevel = 0 %}\n            {% set nestedItem = lineItem %}\n            {% block lineItem %}\n                <tr>\n                    <td>{% if nestedItem.payload.productNumber is defined %}{{ nestedItem.payload.productNumber|u.wordwrap(80) }}{% endif %}</td>\n                    <td>{% if nestedItem.cover is defined and nestedItem.cover is not null %}<img src=\"{{ nestedItem.cover.url }}\" alt=\"\" width=\"75\" height=\"auto\"/>{% endif %}</td>\n                    <td>\n                        {% if nestingLevel > 0 %}\n                            {% for i in 1..nestingLevel %}\n                                <span style=\"position: relative;\">\n                                <span style=\"display: inline-block;\n                                    position: absolute;\n                                    width: 6px;\n                                    height: 20px;\n                                    top: 0;\n                                    border-left:  2px solid rgba(0, 0, 0, 0.15);\n                                    margin-left: {{ i * 10 }}px;\"></span>\n                            </span>\n                            {% endfor %}\n                        {% endif %}\n\n                        <div{% if nestingLevel > 0 %} style=\"padding-left: {{ (nestingLevel + 1) * 10 }}px\"{% endif %}>\n                            {{ nestedItem.label|u.wordwrap(80) }}\n                        </div>\n\n                        {% if nestedItem.payload.options is defined and nestedItem.payload.options|length >= 1 %}\n                            <div>\n                                {% for option in nestedItem.payload.options %}\n                                    {{ option.group }}: {{ option.option }}\n                                    {% if nestedItem.payload.options|last != option %}\n                                        {{ \" | \" }}\n                                    {% endif %}\n                                {% endfor %}\n                            </div>\n                        {% endif %}\n\n                        {% if nestedItem.payload.features is defined and nestedItem.payload.features|length >= 1 %}\n                            {% set referencePriceFeatures = nestedItem.payload.features|filter(feature => feature.type == \'referencePrice\') %}\n                            {% if referencePriceFeatures|length >= 1 %}\n                                {% set referencePriceFeature = referencePriceFeatures|first %}\n                                <div>\n                                    {{ referencePriceFeature.value.purchaseUnit }} {{ referencePriceFeature.value.unitName }}\n                                    ({{ referencePriceFeature.value.price|currency(currencyIsoCode) }} pro {{ referencePriceFeature.value.referenceUnit }} {{ referencePriceFeature.value.unitName }})\n                                </div>\n                            {% endif %}\n                        {% endif %}\n                    </td>\n                    <td style=\"text-align: center\">{{ nestedItem.quantity }}</td>\n                    <td>{{ nestedItem.unitPrice|currency(currencyIsoCode) }}</td>\n                    <td>{{ nestedItem.totalPrice|currency(currencyIsoCode) }}</td>\n                </tr>\n\n                {% if nestedItem.children.count > 0 %}\n                    {% set nestingLevel = nestingLevel + 1 %}\n                    {% for lineItem in nestedItem.children %}\n                        {% set nestedItem = lineItem %}\n                        {{ block(\'lineItem\') }}\n                    {% endfor %}\n                {% endif %}\n            {% endblock %}\n        {% endfor %}\n    </table>\n\n    {% set delivery = order.deliveries.first %}\n\n    {% set displayRounded = order.totalRounding.interval != 0.01 or order.totalRounding.decimals != order.itemRounding.decimals %}\n    {% set decimals = order.totalRounding.decimals %}\n    {% set total = order.price.totalPrice %}\n    {% if displayRounded %}\n        {% set total = order.price.rawTotal %}\n        {% set decimals = order.itemRounding.decimals %}\n    {% endif %}\n    <p>\n        <br>\n        <br>\n        {% for shippingCost in order.deliveries %}\n            Versandkosten: {{ shippingCost.shippingCosts.totalPrice|currency(currencyIsoCode) }}<br>\n        {% endfor %}\n        Gesamtkosten Netto: {{ order.amountNet|currency(currencyIsoCode) }}<br>\n        {% for calculatedTax in order.price.calculatedTaxes %}\n            {% if order.taxStatus is same as(\'net\') %}zzgl.{% else %}inkl.{% endif %} {{ calculatedTax.taxRate }}% MwSt. {{ calculatedTax.tax|currency(currencyIsoCode) }}<br>\n        {% endfor %}\n        {% if not displayRounded %}<strong>{% endif %}Gesamtkosten Brutto: {{ total|currency(currencyIsoCode,decimals=decimals) }}{% if not displayRounded %}</strong>{% endif %}<br>\n        {% if displayRounded %}\n            <strong>Gesamtkosten Brutto gerundet: {{ order.price.totalPrice|currency(currencyIsoCode,decimals=order.totalRounding.decimals) }}</strong><br>\n        {% endif %}\n        <br>\n\n        {% if order.transactions is defined and order.transactions is not empty %}\n            <strong>Gewählte Zahlungsart:</strong> {{ order.transactions.first.paymentMethod.translated.name }}<br>\n            {{ order.transactions.first.paymentMethod.translated.description }}<br>\n            <br>\n        {% endif %}\n\n        {% if delivery %}\n            <strong>Gewählte Versandart:</strong> {{ delivery.shippingMethod.translated.name }}<br>\n            {{ delivery.shippingMethod.translated.description }}<br>\n            <br>\n        {% endif %}\n\n        {% set billingAddress = order.addresses.get(order.billingAddressId) %}\n        <strong>Rechnungsadresse:</strong><br>\n        {{ billingAddress.company }}<br>\n        {{ billingAddress.firstName }} {{ billingAddress.lastName }}<br>\n        {{ billingAddress.street }} <br>\n        {{ billingAddress.zipcode }} {{ billingAddress.city }}<br>\n        {{ billingAddress.country.translated.name }}<br>\n        <br>\n\n        {% if delivery %}\n            <strong>Lieferadresse:</strong><br>\n            {{ delivery.shippingOrderAddress.company }}<br>\n            {{ delivery.shippingOrderAddress.firstName }} {{ delivery.shippingOrderAddress.lastName }}<br>\n            {{ delivery.shippingOrderAddress.street }} <br>\n            {{ delivery.shippingOrderAddress.zipcode}} {{ delivery.shippingOrderAddress.city }}<br>\n            {{ delivery.shippingOrderAddress.country.translated.name }}<br>\n            <br>\n        {% endif %}\n        {% if order.orderCustomer.vatIds %}\n            Ihre Umsatzsteuer-ID: {{ order.orderCustomer.vatIds|first }}\n            Bei erfolgreicher Prüfung und sofern Sie aus dem EU-Ausland\n            bestellen, erhalten Sie Ihre Ware umsatzsteuerbefreit. <br>\n        {% endif %}\n        <br>\n        Den aktuellen Status Ihrer Bestellung können Sie auch jederzeit auf unserer Webseite im  Bereich \"Mein Konto\" - \"Meine Bestellungen\" abrufen: {{ rawUrl(\'frontend.account.order.single.page\', { \'deepLinkCode\': order.deepLinkCode }, salesChannel.domains|first.url) }}\n        <br>\n        Für Rückfragen stehen wir Ihnen jederzeit gerne zur Verfügung.\n        <br>\n        {% if a11yDocuments is defined and a11yDocuments is not empty %}\n            <br>\n            Folgend stellen wir barrierefreie Dokumente als HTML-Version zur Verfügung:<br><br>\n            <ul>\n                {% for a11y in a11yDocuments %}\n                    {% set documentLink = rawUrl(\n                        \'frontend.account.order.single.document.a11y\',\n                        {\n                            documentId: a11y.documentId,\n                            deepLinkCode: a11y.deepLinkCode,\n                            fileType: a11y.fileExtension,\n                        },\n                        salesChannel.domains|first.url\n                    )%}\n                    <li><a href=\"{{ documentLink }}\" target=\"_blank\">{{ documentLink }}</a></li>\n                {% endfor %}\n            </ul>\n            Aus Datenschutzgründen ist für die HTML-Version ein Login erforderlich.<br><br>\n            Im Falle einer Gastbestellung können Sie Ihre E-Mail-Adresse und die Postleitzahl der Rechnungsanschrift verwenden.<br>\n        {% endif %}\n    </p>\n    <br>\n</div>\n',	'{% set currencyIsoCode = order.currency.isoCode %}\nHallo {% if order.orderCustomer.salutation %}{{ order.orderCustomer.salutation.translated.letterName ~ \' \' }}{% endif %}{{ order.orderCustomer.firstName }} {{ order.orderCustomer.lastName }},\n\nIhre Bestellung ist am {{ order.orderDateTime|format_datetime(\'medium\', \'short\', locale=\'de-DE\') }} bei uns eingegangen.\n\nBestellnummer: {{ order.orderNumber }}\n\nSobald ein Zahlungseingang erfolgt ist, erhalten Sie eine separate Benachrichtigung und Ihre Bestellung wird verarbeitet.\n\nDen aktuellen Status Ihrer Bestellung können Sie jederzeit über diesen Link abrufen: {{ rawUrl(\'frontend.account.order.single.page\', { \'deepLinkCode\': order.deepLinkCode }, salesChannel.domains|first.url) }}\nÜber diesen Link können Sie auch die Bestellung bearbeiten, die Zahlungsart wechseln oder nachträglich eine Zahlung durchführen.\n\nInformationen zu Ihrer Bestellung:\n\n{% for lineItem in order.lineItems %}\nPos. {{ loop.index }}\n---------------------\n{% if lineItem.payload.productNumber is defined %}\nArtikel-Nr. {{ lineItem.payload.productNumber|u.wordwrap(80) }},\n{% endif %}\n{% if nestedItem.cover is defined and nestedItem.cover is not null %}\nProduktbild {{ lineItem.cover.alt }},\n{% endif %}\nBeschreibung {{ lineItem.label|u.wordwrap(80) }},\n{% if lineItem.payload.options is defined and lineItem.payload.options|length >= 1 %}\n{% for option in lineItem.payload.options %}\n{{ option.group }}: {{ option.option }}{{ \", \" }}\n{% endfor %}\n{% endif %}\n{% if lineItem.payload.features is defined and lineItem.payload.features|length >= 1 %}\n{% set referencePriceFeatures = lineItem.payload.features|filter(feature => feature.type == \'referencePrice\') %}\n{% if referencePriceFeatures|length >= 1 %}\n{% set referencePriceFeature = referencePriceFeatures|first %}\n{{ referencePriceFeature.value.purchaseUnit }} {{ referencePriceFeature.value.unitName }}({{ referencePriceFeature.value.price|currency(currencyIsoCode) }} pro {{ referencePriceFeature.value.referenceUnit }} {{ referencePriceFeature.value.unitName }}),\n{% endif %}\n{% endif %}\nMenge {{ lineItem.quantity }},\nPreis {{ lineItem.unitPrice|currency(currencyIsoCode) }},\nSumme {{ lineItem.totalPrice|currency(currencyIsoCode) }},\n\n{% endfor %}\n{% set delivery = order.deliveries.first %}\n{% set displayRounded = order.totalRounding.interval != 0.01 or order.totalRounding.decimals != order.itemRounding.decimals %}\n{% set decimals = order.totalRounding.decimals %}\n{% set total = order.price.totalPrice %}\n{% if displayRounded %}\n    {% set total = order.price.rawTotal %}\n    {% set decimals = order.itemRounding.decimals %}\n{% endif %}\n{% for shippingCost in order.deliveries %}\nVersandkosten: {{ shippingCost.shippingCosts.totalPrice|currency(currencyIsoCode) }}\n{% endfor %}\nGesamtkosten Netto: {{ order.amountNet|currency(currencyIsoCode) }}\n{% for calculatedTax in order.price.calculatedTaxes %}\n{% if order.taxStatus is same as(\'net\') %}zzgl.{% else %}inkl.{% endif %} {{ calculatedTax.taxRate }}% MwSt. {{ calculatedTax.tax|currency(currencyIsoCode) }}\n{% endfor %}\nGesamtkosten Brutto: {{ total|currency(currencyIsoCode,decimals=decimals) }}\n{% if displayRounded %}\nGesamtkosten Brutto gerundet: {{ order.price.totalPrice|currency(currencyIsoCode,decimals=order.totalRounding.decimals) }}\n{% endif %}\n\n{% if order.transactions is defined and order.transactions is not empty %}\nGewählte Zahlungsart: {{ order.transactions.first.paymentMethod.translated.name }}\n{{ order.transactions.first.paymentMethod.translated.description }}\n{% endif %}\n\n{% if delivery %}\nGewählte Versandart: {{ delivery.shippingMethod.translated.name }}\n{{ delivery.shippingMethod.translated.description }}\n{% endif %}\n{% set billingAddress = order.addresses.get(order.billingAddressId) %}\nRechnungsadresse:\n{{ billingAddress.company }}\n{{ billingAddress.firstName }} {{ billingAddress.lastName }}\n{{ billingAddress.street }}\n{{ billingAddress.zipcode }} {{ billingAddress.city }}\n{{ billingAddress.country.translated.name }}\n\n{% if delivery %}\nLieferadresse:\n{{ delivery.shippingOrderAddress.company }}\n{{ delivery.shippingOrderAddress.firstName }} {{ delivery.shippingOrderAddress.lastName }}\n{{ delivery.shippingOrderAddress.street }}\n{{ delivery.shippingOrderAddress.zipcode}} {{ delivery.shippingOrderAddress.city }}\n{{ delivery.shippingOrderAddress.country.translated.name }}\n{% endif %}\n\n{% if order.orderCustomer.vatIds %}\nIhre Umsatzsteuer-ID: {{ order.orderCustomer.vatIds|first }}\nBei erfolgreicher Prüfung und sofern Sie aus dem EU-Ausland\nbestellen, erhalten Sie Ihre Ware umsatzsteuerbefreit.\n\n{% endif %}\nDen aktuellen Status Ihrer Bestellung können Sie auch jederzeit auf unserer Webseite im Bereich \"Mein Konto\" - \"Meine Bestellungen\" abrufen: {{ rawUrl(\'frontend.account.order.single.page\', { \'deepLinkCode\': order.deepLinkCode }, salesChannel.domains|first.url) }}\nFür Rückfragen stehen wir Ihnen jederzeit gerne zur Verfügung.\n\n{% if a11yDocuments is defined and a11yDocuments is not empty %}\nFolgend stellen wir barrierefreie Dokumente als HTML-Version zur Verfügung:\n\n{% for a11y in a11yDocuments %}\n{% set documentLink = rawUrl(\n    \'frontend.account.order.single.document.a11y\',\n    {\n        documentId: a11y.documentId,\n        deepLinkCode: a11y.deepLinkCode,\n        fileType: a11y.fileExtension,\n    },\n    salesChannel.domains|first.url\n)%}\n- {{ documentLink }}\n{% endfor %}\n\nAus Datenschutzgründen ist für die HTML-Version ein Login erforderlich.\nIm Falle einer Gastbestellung können Sie Ihre E-Mail-Adresse und die Postleitzahl der Rechnungsanschrift verwenden.\n{% endif %}\n',	NULL,	'2026-01-14 07:30:47.558',	NULL),
(UNHEX('019BBB6A0A8D71679C88F8590EF0013D'),	UNHEX('019BBB6ADAF07027AAE9AFD1663F88B7'),	'{{ salesChannel.name }}',	'Your sign-up with {{ salesChannel.translated.name }}',	'Registration confirmation',	'<div style=\"font-family:arial; font-size:12px;\">\n            <p>\n                {{ customer.salutation.translated.letterName }} {{ customer.firstName }} {{ customer.lastName }},<br/>\n                <br/>\n                thank you for your signing up with our Shop.<br/>\n                You will gain access via the email address <strong>{{ customer.email }}</strong> and the password you have chosen.<br/>\n                You can change your password anytime.\n            </p>\n        </div>',	'{{ customer.salutation.translated.letterName }} {{customer.firstName}} {{ customer.lastName }},\n\n                thank you for your signing up with our Shop.\n                You will gain access via the email address {{ customer.email }} and the password you have chosen.\n                You can change your password anytime.\n        ',	NULL,	'2026-01-14 07:30:47.567',	NULL),
(UNHEX('019BBB6A0A8D71679C88F8590EF0013D'),	UNHEX('2FBB5FE2E29A4D70AA5854CE7CE3E20B'),	'{{ salesChannel.name }}',	'Deine Registrierung bei {{ salesChannel.name }}',	'Registrierungsbestätigung',	'<div style=\"font-family:arial; font-size:12px;\">\n            <p>\n                {{ customer.salutation.translated.letterName }} {{customer.firstName}} {{ customer.lastName }},<br/>\n                <br/>\n                vielen Dank für Ihre Anmeldung in unserem Shop.<br/>\n                Sie erhalten Zugriff über Ihre E-Mail-Adresse <strong>{{ customer.email }}</strong> und dem von Ihnen gewählten Kennwort.<br/>\n                Sie können Ihr Kennwort jederzeit nachträglich ändern.\n            </p>\n        </div>',	'{{ customer.salutation.translated.letterName }} {{customer.firstName}} {{ customer.lastName }},\n\n                vielen Dank für Ihre Anmeldung in unserem Shop.\n                Sie erhalten Zugriff über Ihre E-Mail-Adresse {{ customer.email }} und dem von Ihnen gewählten Kennwort.\n                Sie können Ihr Kennwort jederzeit nachträglich ändern.\n',	NULL,	'2026-01-14 07:30:47.568',	NULL),
(UNHEX('019BBB6A0A95722CA8DA1936B9D87C4E'),	UNHEX('019BBB6ADAF07027AAE9AFD1663F88B7'),	'{{ salesChannel.name }}',	'Password reset - {{ salesChannel.name }}',	'Password reset request',	'<div style=\"font-family:arial; font-size:12px;\">\n    <p>\n        {{ customer.salutation.translated.letterName }} {{ customer.firstName }} {{ customer.lastName }},<br/>\n        <br/>\n        there has been a request to reset you Password in the Shop {{ salesChannel.translated.name }}\n        Please confirm the link below to specify a new password.<br/>\n        <br/>\n        <a href=\"{{ resetUrl }}\">Reset password</a><br/>\n        <br/>\n        This link is valid for the next 2 hours. After that you have to request a new confirmation link.<br/>\n        If you do not want to reset your password, please ignore this email. No changes will be made.\n    </p>\n</div>\n',	'{{ customer.salutation.translated.letterName }} {{customer.firstName}} {{ customer.lastName }},\n\nthere has been a request to reset you Password in the Shop {{ salesChannel.translated.name }}\nPlease confirm the link below to specify a new password.\n\nReset password: {{ resetUrl }}\n\nThis link is valid for the next 2 hours. After that you have to request a new confirmation link.\nIf you do not want to reset your password, please ignore this email. No changes will be made.',	NULL,	'2026-01-14 07:30:47.574',	NULL),
(UNHEX('019BBB6A0A95722CA8DA1936B9D87C4E'),	UNHEX('2FBB5FE2E29A4D70AA5854CE7CE3E20B'),	'{{ salesChannel.name }}',	'Password zurücksetzen - {{ salesChannel.name }}',	'Anfrage zum Zurücksetzen des Passworts',	'<div style=\"font-family:arial; font-size:12px;\">\n    <p>\n        Hallo {{ customer.salutation.translated.letterName }} {{customer.firstName}} {{ customer.lastName }},<br/>\n        <br/>\n        im Shop {{ salesChannel.translated.name }} wurde eine Anfrage gestellt, um Ihr Passwort zurück zu setzen.\n        Bitte bestätigen Sie den unten stehenden Link, um ein neues Passwort zu definieren.<br/>\n        <br/>\n        <a href=\"{{ resetUrl }}\">Passwort zurücksetzen</a><br/>\n        <br/>\n        Dieser Link ist nur für die nächsten 2 Stunden gültig. Danach muss das Zurücksetzen des Passwortes erneut beantragt werden.\n        Falls Sie Ihr Passwort nicht zurücksetzen möchten, ignorieren Sie diese E-Mail - es wird dann keine Änderung vorgenommen.\n    </p>\n</div>',	'Hallo {{ customer.salutation.translated.letterName }} {{customer.firstName}} {{ customer.lastName }},\n\nim Shop {{ salesChannel.translated.name }} wurde eine Anfrage gestellt, um Ihr Passwort zurück zu setzen.\nBitte bestätigen Sie den unten stehenden Link, um ein neues Passwort zu definieren.\n\nPasswort zurücksetzen: {{ resetUrl }}\n\nDieser Link ist nur für die nächsten 2 Stunden gültig. Danach muss das Zurücksetzen des Passwortes erneut beantragt werden.\nFalls Sie Ihr Passwort nicht zurücksetzen möchten, ignorieren Sie diese E-Mail - es wird dann keine Änderung vorgenommen.',	NULL,	'2026-01-14 07:30:47.576',	NULL),
(UNHEX('019BBB6A0A9C72F389F094A0B41C6A09'),	UNHEX('019BBB6ADAF07027AAE9AFD1663F88B7'),	'{{ salesChannel.name }}',	'Your merchant account has been unlocked - {{ salesChannel.name }}',	'Customer Group Change accepted',	'<div style=\"font-family:arial; font-size:12px;\">\n    <p>\n        Hello,<br/>\n        <br/>\n        your merchant account at {{ salesChannel.translated.name }} has been unlocked.<br/>\n        From now on, we will charge you the net purchase price.\n    </p>\n</div>\n',	'Hello,\n\nyour merchant account at {{ salesChannel.translated.name }} has been unlocked.\nFrom now on, we will charge you the net purchase price.\n',	NULL,	'2026-01-14 07:30:47.581',	NULL),
(UNHEX('019BBB6A0A9C72F389F094A0B41C6A09'),	UNHEX('2FBB5FE2E29A4D70AA5854CE7CE3E20B'),	'{{ salesChannel.name }}',	'Ihr Händleraccount wurde freigeschaltet - {{ salesChannel.name }}',	'Kundengruppenwechsel freigeschaltet',	'<div style=\"font-family:arial; font-size:12px;\">\n    <p>\n        Hallo,<br/>\n        <br/>\n        ihr Händlerkonto bei {{ salesChannel.translated.name }} wurde freigeschaltet.<br/>\n        Von nun an werden wir Ihnen den Netto-Preis berechnen.\n    </p>\n</div>\n',	'Hallo,\n\nihr Händlerkonto bei {{ salesChannel.translated.name }} wurde freigeschaltet.\nVon nun an werden wir Ihnen den Netto-Preis berechnen.\n',	NULL,	'2026-01-14 07:30:47.583',	NULL),
(UNHEX('019BBB6A0AA072B7A7EFFAA3542B8E14'),	UNHEX('019BBB6ADAF07027AAE9AFD1663F88B7'),	'{{ salesChannel.name }}',	'Your trader account has not been accepted - {{ salesChannel.name }}',	'Customer Group Change rejected',	'<div style=\"font-family:arial; font-size:12px;\">\n    <p>\n        Hello,<br/>\n        <br/>\n        thank you for your interest in our trade prices.\n        Unfortunately, we do not have a trading license yet so that we cannot accept you as a merchant.<br/>\n        In case of further questions please do not hesitate to contact us via telephone, fax or email.\n    </p>\n</div>\n',	'Hello,\n\nthank you for your interest in our trade prices. Unfortunately,\nwe do not have a trading license yet so that we cannot accept you as a merchant.\nIn case of further questions please do not hesitate to contact us via telephone, fax or email.\n',	NULL,	'2026-01-14 07:30:47.586',	NULL),
(UNHEX('019BBB6A0AA072B7A7EFFAA3542B8E14'),	UNHEX('2FBB5FE2E29A4D70AA5854CE7CE3E20B'),	'{{ salesChannel.name }}',	'Ihr Händleraccountantrag wurde abgelehnt - {{ salesChannel.name }}',	'Kundengruppenwechsel abgelehnt',	'<div style=\"font-family:arial; font-size:12px;\">\n    <p>\n        Hallo,<br/>\n        <br/>\n        vielen Dank für ihr Interesse an unseren Großhandelspreisen. Leider liegt uns bisher keine <br/>\n        Händlerauthentifizierung vor, und daher können wir Ihre Anfrage nicht bestätigen. <br/>\n        Bei weiteren Fragen kontaktieren Sie uns gerne per Telefon, Fax oder E-Mail. <br/>\n    </p>\n</div>\n',	'Hallo,\n\nvielen Dank für ihr Interesse an unseren Großhandelspreisen. Leider liegt uns bisher keine\nHändlerauthentifizierung vor, und daher können wir Ihre Anfrage nicht bestätigen.\nBei weiteren Fragen kontaktieren Sie uns gerne per Telefon, Fax oder E-Mail.\n',	NULL,	'2026-01-14 07:30:47.587',	NULL),
(UNHEX('019BBB6A104E72429FD7D8E505EA5ED9'),	UNHEX('019BBB6ADAF07027AAE9AFD1663F88B7'),	'Shopware Administration',	'Password recovery',	'',	'<div style=\"font-family:arial; font-size:12px;\">\n    <p>\n        Dear {{ userRecovery.user.firstName }} {{ userRecovery.user.lastName }},<br/>\n        <br/>\n        there has been a request to reset your password.\n        Please confirm the link below to specify a new password.<br/>\n        <br/>\n        <a href=\"{{ resetUrl }}\">Reset password</a><br/>\n        <br/>\n        This link is valid for the next 2 hours. After that you have to request a new confirmation link.<br/>\n        If you do not want to reset your password, please ignore this email. No changes will be made.\n    </p>\n</div>',	'        Dear {{ userRecovery.user.firstName }} {{ userRecovery.user.lastName }},\n\n        there has been a request to reset your password.\n        Please confirm the link below to specify a new password.\n\n        Reset password: {{ resetUrl }}\n\n        This link is valid for the next 2 hours. After that you have to request a new confirmation link.\n        If you do not want to reset your password, please ignore this email. No changes will be made.',	NULL,	'2026-01-14 07:30:49.041',	NULL),
(UNHEX('019BBB6A104E72429FD7D8E505EA5ED9'),	UNHEX('2FBB5FE2E29A4D70AA5854CE7CE3E20B'),	'Shopware Administration',	'Password-Wiederherstellung',	'',	'<div style=\"font-family:arial; font-size:12px;\">\n    <p>\n        Hallo {{ userRecovery.user.firstName }} {{ userRecovery.user.lastName }},<br/>\n        <br/>\n        es wurde eine Anfrage gestellt, um Ihr Passwort zurück zu setzen.\n        Bitte bestätigen Sie den unten stehenden Link, um ein neues Passwort zu definieren.<br/>\n        <br/>\n        <a href=\"{{ resetUrl }}\">Passwort zurücksetzen</a><br/>\n        <br/>\n        Dieser Link ist nur für die nächsten 2 Stunden gültig. Danach muss das Zurücksetzen des Passwortes erneut beantragt werden.\n        Falls Sie Ihr Passwort nicht zurücksetzen möchten, ignorieren Sie diese E-Mail - es wird dann keine Änderung vorgenommen.\n    </p>\n</div>',	'        Hallo {{ userRecovery.user.firstName }} {{ userRecovery.user.lastName }},\n\n        es wurde eine Anfrage gestellt, um Ihr Passwort zurück zu setzen.\n        Bitte bestätigen Sie den unten stehenden Link, um ein neues Passwort zu definieren.\n\n        Passwort zurücksetzen: {{ resetUrl }}\n\n        Dieser Link ist nur für die nächsten 2 Stunden gültig. Danach muss das Zurücksetzen des Passwortes erneut beantragt werden.\n        Falls Sie Ihr Passwort nicht zurücksetzen möchten, ignorieren Sie diese E-Mail - es wird dann keine Änderung vorgenommen.',	NULL,	'2026-01-14 07:30:49.042',	NULL),
(UNHEX('019BBB6A185B72D590DB630C88DE8207'),	UNHEX('019BBB6ADAF07027AAE9AFD1663F88B7'),	'{{ salesChannel.name }}',	'Contact form received - {{ salesChannel.name }}',	'Contact form received',	'<div style=\"font-family:arial; font-size:12px;\">\n    <p>\n        The following Message was sent to you via the contact form.<br/>\n        <br/>\n        Contact name: {{ contactFormData.firstName }} {{ contactFormData.lastName }}\n        <br/>\n        Contact email address: {{ contactFormData.email }}\n        <br/>\n        Phone: {{ contactFormData.phone }}<br/>\n        <br/>\n        Subject: {{ contactFormData.subject }}<br/>\n        <br/>\n        Message:<br/>\n        {{ contactFormData.comment|nl2br }}<br/>\n    </p>\n</div>\n',	'The following Message was sent to you via the contact form.\n\nContact name: {{ contactFormData.firstName }} {{ contactFormData.lastName }}\nContact email address: {{ contactFormData.email }}\nPhone: {{ contactFormData.phone }}\n\nSubject: {{ contactFormData.subject }}\n\nMessage:\n{{ contactFormData.comment }}\n',	NULL,	'2026-01-14 07:30:51.100',	NULL),
(UNHEX('019BBB6A185B72D590DB630C88DE8207'),	UNHEX('2FBB5FE2E29A4D70AA5854CE7CE3E20B'),	'{{ salesChannel.name }}',	'Kontaktanfrage erhalten - {{ salesChannel.name }}',	'Kontaktanfrage erhalten',	'<div style=\"font-family:arial; font-size:12px;\">\n    <p>\n        Folgende Nachricht wurde an Sie via Kontakt-Formular gesendet.<br/>\n        <br/>\n        Name: {{ contactFormData.firstName }} {{ contactFormData.lastName }}\n        <br/>\n        Kontakt E-Mail: {{ contactFormData.email }}<br/>\n        <br>\n        Telefonnummer: {{ contactFormData.phone }}<br/>\n        <br/>\n        Betreff: {{ contactFormData.subject }}<br/>\n        <br/>\n        Message:<br/>\n        {{ contactFormData.comment|nl2br }}<br/>\n    </p>\n</div>\n',	'Folgende Nachricht wurde an Sie via Kontakt-Formular gesendet.\n\nName: {{ contactFormData.firstName }} {{ contactFormData.lastName }}\nKontakt E-Mail: {{ contactFormData.email }}\n\nTelefonnummer: {{ contactFormData.phone }}\n\nBetreff: {{ contactFormData.subject }}\n\nNachricht:\n{{ contactFormData.comment }}\n',	NULL,	'2026-01-14 07:30:55.000',	NULL),
(UNHEX('019BBB6A1A4E713C9483C61FBACF0C49'),	UNHEX('019BBB6ADAF07027AAE9AFD1663F88B7'),	'{{ shopName }}',	'Password recovery',	'',	'<div style=\"font-family:arial; font-size:12px;\">\n    <p>\n        Hello {{ customerRecovery.customer.firstName }} {{ customerRecovery.customer.lastName }},<br/>\n        <br/>\n        You have requested a new password for your {{ shopName }} account.\n        Click on the following link to reset your password:<br/>\n        <br/>\n        <a href=\"{{ resetUrl }}\">{{ resetUrl }}</a><br/>\n        <br/>\n        This link is valid for the next 2 hours.\n        If you don\'t want to reset your password, ignore this email and no changes will be made.<br/>\n        <br/>\n        Yours sincerely\n        Your {{ shopName }} team\n    </p>\n</div>',	'        Hello {{ customerRecovery.customer.firstName }} {{ customerRecovery.customer.lastName }},\n\n        You have requested a new password for your {{ shopName }} account.\n        Click on the following link to reset your password:\n\n        {{ resetUrl }}\n\n        This link is valid for the next 2 hours.\n        If you don\'t want to reset your password, ignore this email and no changes will be made.\n\n        Yours sincerely\n        Your {{ shopName }}-Team',	NULL,	'2026-01-14 07:30:51.600',	NULL),
(UNHEX('019BBB6A1A4E713C9483C61FBACF0C49'),	UNHEX('2FBB5FE2E29A4D70AA5854CE7CE3E20B'),	'{{ shopName }}',	'Password-Wiederherstellung',	'',	'<div style=\"font-family:arial; font-size:12px;\">\n    <p>\n        Hallo {{ customerRecovery.customer.firstName }} {{ customerRecovery.customer.lastName }},<br/>\n        <br/>\n        Sie haben ein neues Passwort für Ihren {{ shopName }}-Account angefordert.\n        Klicken Sie auf folgenden Link, um Ihr Passwort zurückzusetzen:<br/>\n        <br/>\n        <a href=\"{{ resetUrl }}\">{{ resetUrl }}</a><br/>\n        <br/>\n        Dieser Link ist für die nächsten 2 Stunden gültig.\n        Falls Sie Ihr Passwort nicht zurücksetzen möchten, ignorieren Sie diese E-Mail - es wird dann keine Änderung vorgenommen.<br/>\n        <br/>\n        Mit freundlichen Grüßen\n        Ihr {{ shopName }}-Team\n    </p>\n</div>',	'        Hallo {{ customerRecovery.customer.firstName }} {{ customerRecovery.customer.lastName }},\n\n        Sie haben ein neues Passwort für Ihren {{ shopName }}-Account angefordert.\n        Klicken Sie auf folgenden Link, um Ihr Passwort zurückzusetzen:\n\n        {{ resetUrl }}\n\n        Dieser Link ist für die nächsten 2 Stunden gültig.\n        Falls Sie Ihr Passwort nicht zurücksetzen möchten, ignorieren Sie diese E-Mail - es wird dann keine Änderung vorgenommen.\n\n        Mit freundlichen Grüßen\n        Ihr {{ shopName }}-Team',	NULL,	'2026-01-14 07:30:51.602',	NULL),
(UNHEX('019BBB6A1C3A71458CFC111235619C76'),	UNHEX('019BBB6ADAF07027AAE9AFD1663F88B7'),	'{{ salesChannel.name }}',	'New document for your order',	NULL,	'<div style=\"font-family:arial; font-size:12px;\">\n    <br/>\n    <p>\n        {% if order.orderCustomer.salutation %}{{ order.orderCustomer.salutation.translated.letterName ~ \' \' }}{% endif %}{{ order.orderCustomer.firstName }} {{ order.orderCustomer.lastName }},<br/>\n        <br/>\n        the status of your delivery at {{ salesChannel.translated.name }} (Number: {{ order.orderNumber }}) on {{ order.orderDateTime|format_datetime(\'medium\', \'short\', locale=\'en-GB\') }} has changed.<br/>\n        <strong>The new status is as follows: {{ order.deliveries.first.stateMachineState.translated.name }}.</strong><br/>\n        <br/>\n        You can check the current status of your order on our website under \"My account\" - \"My orders\" anytime: {{ rawUrl(\'frontend.account.order.single.page\', { \'deepLinkCode\': order.deepLinkCode }, salesChannel.domains|first.url) }}\n        </br>\n        However, in case you have purchased without a registration or a customer account, you do not have this option.\n        <br><br>\n        {% if a11yDocuments %}\n            For better accessibility we also provide an HTML version of the documents here:<br><br>\n\n            {% for a11y in a11yDocuments %}\n                {% set documentLink = rawUrl(\n                    \'frontend.account.order.single.document.a11y\',\n                    {\n                        documentId: a11y.documentId,\n                        deepLinkCode: a11y.deepLinkCode,\n                        fileType: a11y.fileExtension,\n                    },\n                    salesChannel.domains|first.url\n                )%}\n\n                - <a href=\"{{ documentLink }}\" target=\"_blank\">{{ documentLink }}</a> <br>\n            {% endfor %}<br>\n            For data protection reasons the HTML version requires a login. <br><br>\n            In case of a guest order, you can use your email address and postal code of the billing address.<br>\n        {% endif %}\n    </p>\n</div>\n',	'{% if order.orderCustomer.salutation %}{{ order.orderCustomer.salutation.translated.letterName ~ \' \' }}{% endif %}{{ order.orderCustomer.firstName }} {{ order.orderCustomer.lastName }},\n\nthe status of your delivery at {{ salesChannel.translated.name }} (Number: {{ order.orderNumber }}) on {{ order.orderDateTime|format_datetime(\'medium\', \'short\', locale=\'en-GB\') }}  has changed.\nThe new status is as follows: {{ order.deliveries.first.stateMachineState.translated.name }}.\n\nYou can check the current status of your order on our website under \"My account\" - \"My orders\" anytime: {{ rawUrl(\'frontend.account.order.single.page\', { \'deepLinkCode\': order.deepLinkCode }, salesChannel.domains|first.url) }}\nHowever, in case you have purchased without a registration or a customer account, you do not have this option.\n\n{% if a11yDocuments %}\n    For better accessibility we also provide an HTML version of the documents here:\n\n    {% for a11y in a11yDocuments %}\n        {% set documentLink = rawUrl(\n            \'frontend.account.order.single.document.a11y\',\n            {\n                documentId: a11y.documentId,\n                \'deepLinkCode\': a11y.deepLinkCode,\n                fileType: a11y.fileExtension,\n            },\n            salesChannel.domains|first.url\n        )%}\n\n        - {{ documentLink }}\n    {% endfor %}\n\n    For data protection reasons the HTML version requires a login.\n\n    In case of a guest order, you can use your email address and postal code of the billing address.\n{% endif %}\n',	NULL,	'2026-01-14 07:31:32.459',	NULL),
(UNHEX('019BBB6A1C3A71458CFC111235619C76'),	UNHEX('2FBB5FE2E29A4D70AA5854CE7CE3E20B'),	'{{ salesChannel.name }}',	'Neues Dokument für Ihre Bestellung',	NULL,	'<div style=\"font-family:arial; font-size:12px;\">\n    <br/>\n    <p>\n        {% if order.orderCustomer.salutation %}{{ order.orderCustomer.salutation.translated.letterName ~ \' \' }}{% endif %}{{ order.orderCustomer.firstName }} {{ order.orderCustomer.lastName }},<br/>\n        <br/>\n        der Lieferstatus für Ihre Bestellung bei {{ salesChannel.translated.name }} (Number: {{ order.orderNumber }}) vom {{ order.orderDateTime|format_datetime(\'medium\', \'short\', locale=\'de-DE\') }} hat sich geändert.<br/>\n        <strong>Die Bestellung hat jetzt den Lieferstatus: {{ order.deliveries.first.stateMachineState.translated.name }}.</strong><br/>\n        <br/>\n        Den aktuellen Status Ihrer Bestellung können Sie auch jederzeit auf unserer Webseite im  Bereich \"Mein Konto\" - \"Meine Bestellungen\" abrufen: {{ rawUrl(\'frontend.account.order.single.page\', { \'deepLinkCode\': order.deepLinkCode }, salesChannel.domains|first.url) }}\n        </br>\n        Sollten Sie allerdings den Kauf ohne Registrierung, also ohne Anlage eines Kundenkontos, gewählt haben, steht Ihnen diese Möglichkeit nicht zur Verfügung.\n        <br><br>\n        {% if a11yDocuments %}\n            Folgend stellen wir barrierefreie Dokumente als HTML-Version zur Verfügung:<br><br>\n            {% for a11y in a11yDocuments %}\n                {% set documentLink = rawUrl(\n                    \'frontend.account.order.single.document.a11y\',\n                    {\n                        documentId: a11y.documentId,\n                        deepLinkCode: a11y.deepLinkCode,\n                        fileType: a11y.fileExtension,\n                    },\n                    salesChannel.domains|first.url\n                )%}\n\n                - <a href=\"{{ documentLink }}\" target=\"_blank\">{{ documentLink }}</a> <br>\n            {% endfor %}<br>\n\n            Aus Datenschutzgründen ist für die HTML-Version ein Login erforderlich.<br><br>\n            Im Falle einer Gastbestellung können Sie Ihre E-Mail-Adresse und die Postleitzahl der Rechnungsanschrift verwenden.<br>\n        {% endif %}\n    </p>\n</div>\n',	'{% if order.orderCustomer.salutation %}{{ order.orderCustomer.salutation.translated.letterName ~ \' \' }}{% endif %}{{ order.orderCustomer.firstName }} {{ order.orderCustomer.lastName }},\n\nder Lieferstatus für Ihre Bestellung bei {{ salesChannel.translated.name }} (Number: {{ order.orderNumber }}) vom {{ order.orderDateTime|format_datetime(\'medium\', \'short\', locale=\'de-DE\') }} hat sich geändert!\nDie Bestellung hat jetzt den Lieferstatus: {{ order.deliveries.first.stateMachineState.translated.name }}.\n\nDen aktuellen Status Ihrer Bestellung können Sie auch jederzeit auf unserer Webseite im  Bereich \"Mein Konto\" - \"Meine Bestellungen\" abrufen: {{ rawUrl(\'frontend.account.order.single.page\', { \'deepLinkCode\': order.deepLinkCode }, salesChannel.domains|first.url) }}\nSollten Sie allerdings den Kauf ohne Registrierung, also ohne Anlage eines Kundenkontos, gewählt haben, steht Ihnen diese Möglichkeit nicht zur Verfügung.\n\n{% if a11yDocuments %}\n    Folgend stellen wir barrierefreie Dokumente als HTML-Version zur Verfügung:\n\n    {% for a11y in a11yDocuments %}\n        {% set documentLink = rawUrl(\n            \'frontend.account.order.single.document.a11y\',\n            {\n                documentId: a11y.documentId,\n                deepLinkCode: a11y.deepLinkCode,\n                fileType: a11y.fileExtension,\n            },\n            salesChannel.domains|first.url\n        )%}\n\n        - {{ documentLink }}\n    {% endfor %}\n    Aus Datenschutzgründen ist für die HTML-Version ein Login erforderlich.\n\n    Im Falle einer Gastbestellung können Sie Ihre E-Mail-Adresse und die Postleitzahl der Rechnungsanschrift verwenden.\n{% endif %}\n',	NULL,	'2026-01-14 07:31:32.461',	NULL),
(UNHEX('019BBB6A1C4572C4975F16624192D7A9'),	UNHEX('019BBB6ADAF07027AAE9AFD1663F88B7'),	'{{ salesChannel.name }}',	'New document for your order',	NULL,	'<div style=\"font-family:arial; font-size:12px;\">\n    <br/>\n    <p>\n        {% if order.orderCustomer.salutation %}{{ order.orderCustomer.salutation.translated.letterName ~ \' \' }}{% endif %}{{ order.orderCustomer.firstName }} {{ order.orderCustomer.lastName }},<br/>\n        <br/>\n        the status of your delivery at {{ salesChannel.translated.name }} (Number: {{ order.orderNumber }}) on {{ order.orderDateTime|format_datetime(\'medium\', \'short\', locale=\'en-GB\') }} has changed.<br/>\n        <strong>The new status is as follows: {{ order.deliveries.first.stateMachineState.translated.name }}.</strong><br/>\n        <br/>\n        You can check the current status of your order on our website under \"My account\" - \"My orders\" anytime: {{ rawUrl(\'frontend.account.order.single.page\', { \'deepLinkCode\': order.deepLinkCode }, salesChannel.domains|first.url) }}\n        </br>\n        However, in case you have purchased without a registration or a customer account, you do not have this option.\n        <br><br>\n        {% if a11yDocuments %}\n            For better accessibility we also provide an HTML version of the documents here:<br><br>\n\n            {% for a11y in a11yDocuments %}\n                {% set documentLink = rawUrl(\n                    \'frontend.account.order.single.document.a11y\',\n                    {\n                        documentId: a11y.documentId,\n                        deepLinkCode: a11y.deepLinkCode,\n                        fileType: a11y.fileExtension,\n                    },\n                    salesChannel.domains|first.url\n                )%}\n\n                - <a href=\"{{ documentLink }}\" target=\"_blank\">{{ documentLink }}</a> <br>\n            {% endfor %}<br>\n            For data protection reasons the HTML version requires a login. <br><br>\n            