(UNHEX('019BBB6AC62B73CC9246B14C940936C5'),	UNHEX('019BBB6ADAF07027AAE9AFD1663F88B7'),	'{{ salesChannel.name }}',	'Customer password changed',	NULL,	'<div style=\"font-family:arial; font-size:12px;\">\n    Hello {{ customer.firstName }} {{ customer.lastName }},<br/>\n    <br/>\n    Your {{ shopName }} account password has been changed successfully. <br/>\n</div>\n',	'Hello {{ customer.firstName }} {{ customer.lastName }},\n\nYour {{ shopName }} account password has been changed successfully.\n',	NULL,	'2026-01-14 07:31:35.596',	NULL),
(UNHEX('019BBB6AC62B73CC9246B14C940936C5'),	UNHEX('2FBB5FE2E29A4D70AA5854CE7CE3E20B'),	'{{ salesChannel.name }}',	'Kunden-Password geändert',	NULL,	'<div style=\"font-family:arial; font-size:12px;\">\n    Hallo {{ customer.firstName }} {{ customer.lastName }},<br/>\n    <br/>\n    Das Passwort für Ihr {{ shopName }}-Konto wurde erfolgreich geändert. <br/>\n</div>\n',	'Hallo {{ customer.firstName }} {{ customer.lastName }},\n\nDas Passwort für Ihr {{ shopName }}-Konto wurde erfolgreich geändert.\n',	NULL,	'2026-01-14 07:31:35.596',	NULL);

DROP TABLE IF EXISTS `mail_template_type`;
CREATE TABLE `mail_template_type` (
  `id` binary(16) NOT NULL,
  `technical_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `available_entities` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `created_at` datetime(3) NOT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `template_data` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq.mail_template_type.technical_name` (`technical_name`),
  CONSTRAINT `json.mail_template_type.available_entities` CHECK (json_valid(`available_entities`))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

