  CONSTRAINT `json.order_delivery_position.price` CHECK (json_valid(`price`))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `order_line_item`;
