DROP TABLE IF EXISTS `script`;
CREATE TABLE `script` (
  `id` binary(16) NOT NULL,
  `script` longtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `hook` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `name` varchar(1024) COLLATE utf8mb4_unicode_ci NOT NULL,
  `active` tinyint(1) NOT NULL,
  `app_id` binary(16) DEFAULT NULL,
  `created_at` datetime(3) NOT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx.app_script.hook` (`hook`),
  KEY `fk.app_script.app_id` (`app_id`),
  CONSTRAINT `fk.app_script.app_id` FOREIGN KEY (`app_id`) REFERENCES `app` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `script` (`id`, `script`, `hook`, `name`, `active`, `app_id`, `created_at`, `updated_at`) VALUES
(UNHEX('019BBB6B521570B996B309E7FCA0F3DA'),	'// Resources/scripts/suggest-page-loaded/suggest-page-loaded.twig\n{% import \'include/spatial-preview-repository.twig\' as spatialPreviewRepository %}\n\n{% set page = hook.page %}\n{# @var page \\Shopware\\Storefront\\Page\\Suggest\\SuggestPage  #}\n\n{% set permissionGranted = services.acl.can(\'ce_spatial_preview:read\') %}\n\n{% if permissionGranted %}\n    {% set products = page.searchResult.entities %}\n    {% set coverIds = products|map(product => product.cover.mediaId) %}\n    {% set previewMedia = spatialPreviewRepository.getPreviewFromMedia(coverIds) %}\n\n    {% for preview in previewMedia %}\n        {% set product = products|filter(product => product.cover.media.id == preview.mediaId)|first %}\n        {% if product is not null %}\n            {% do product.cover.assign({\'media\': preview.preview}) %}\n        {% endif %}\n    {% endfor %}\n{% endif %}\n',	'suggest-page-loaded',	'suggest-page-loaded/suggest-page-loaded.twig',	1,	UNHEX('019BBB6B4D3F7373A6848623014E0859'),	'2026-01-14 07:32:11.414',	'2026-01-14 07:32:11.940'),
(UNHEX('019BBB6B521570B996B309E7FD42978C'),	'{% import \'include/spatial-preview-repository.twig\' as spatialPreviewRepository %}\n\n{# CMS Element - 3D Object #}\n{% set spatialViewerBlocks = page.cmsPage.sections.blocks|filter(block => block.type == \'spatial-viewer\') %}\n\n{% for spatialViewerBlock in spatialViewerBlocks %}\n    {% set spatialViewerSlots = spatialViewerBlock.slots|filter(slot => slot.type == \'spatial-viewer\') %}\n\n    {% for spatialViewerSlot in spatialViewerSlots %}\n        {% set media = spatialViewerSlot.data %}\n        {% set previewMedia = spatialPreviewRepository.getPreviewFromMedia([media.id])|first %}\n\n        {% if previewMedia %}\n            {% do media.addExtension(\'preview\', previewMedia.preview) %}\n        {% endif %}\n    {% endfor %}\n{% endfor %}\n',	'include',	'include/cms-element-spatial-viewer.twig',	1,	UNHEX('019BBB6B4D3F7373A6848623014E0859'),	'2026-01-14 07:32:11.414',	'2026-01-14 07:32:11.941'),
(UNHEX('019BBB6B521570B996B309E7FD606B3B'),	'{% import \'include/spatial-preview-repository.twig\' as spatialPreviewRepository %}\n\n{# CMS Element - Product Listing#}\n{% set productListingSlots = page.cmsPage.sections.blocks.slots|filter(slot => slot.type == \'product-listing\') %}\n\n{% for productListingSlot in productListingSlots %}\n    {% set products = productListingSlot.data.listing.elements %}\n\n    {% if products|length > 0 %}\n        {% set coverIds = products|map(product => product.cover.mediaId) %}\n        {% set previewMedia = spatialPreviewRepository.getPreviewFromMedia(coverIds) %}\n\n        {% for preview in previewMedia %}\n            {% set product = products|filter(product => product.cover.mediaId == preview.mediaId)|first %}\n\n            {% if product %}\n                {% do product.cover.assign({\'media\': preview.preview}) %}\n            {% endif %}\n        {% endfor %}\n     {% endif %}\n{% endfor %}\n',	'include',	'include/cms-element-product-listing.twig',	1,	UNHEX('019BBB6B4D3F7373A6848623014E0859'),	'2026-01-14 07:32:11.414',	'2026-01-14 07:32:11.941'),
(UNHEX('019BBB6B521570B996B309E7FDD7DA9E'),	'{% import \'include/spatial-preview-repository.twig\' as spatialPreviewRepository %}\n\n{# CMS Element - Product slider #}\n{% set productSliderSlots = page.cmsPage.sections.blocks.slots|filter(slot => slot.type == \'product-slider\') %}\n\n{% for productSliderSlots in productSliderSlots %}\n    {% set products = productSliderSlots.data.products %}\n\n    {% if products|length > 0 %}\n        {% set coverIds = products|map(product => product.cover.mediaId) %}\n        {% set previewMedia = spatialPreviewRepository.getPreviewFromMedia(coverIds) %}\n\n        {% for preview in previewMedia %}\n            {% set product = products|filter(product => product.cover.mediaId == preview.mediaId)|first %}\n\n            {% if product %}\n                {% do product.cover.assign({\'media\': preview.preview}) %}\n            {% endif %}\n        {% endfor %}\n    {% endif %}\n{% endfor %}\n',	'include',	'include/cms-element-product-slider.twig',	1,	UNHEX('019BBB6B4D3F7373A6848623014E0859'),	'2026-01-14 07:32:11.414',	'2026-01-14 07:32:11.941'),
(UNHEX('019BBB6B521570B996B309E7FE64B659'),	'{% import \'include/spatial-preview-repository.twig\' as spatialPreviewRepository %}\n\n{# CMS Element - Cross Selling #}\n{% set crossSellingSlots = page.cmsPage.sections.blocks.slots|filter(slot => slot.type == \'cross-selling\') %}\n\n{% for crossSellingSlot in crossSellingSlots %}\n    {% set crossSellings = crossSellingSlot.data.crossSellings %}\n\n    {% for crossSelling in crossSellings %}\n        {% set products = crossSelling.products %}\n\n        {% if products|length > 0 %}\n            {% set coverIds = products|map(product => product.cover.mediaId) %}\n            {% set previewMedia = spatialPreviewRepository.getPreviewFromMedia(coverIds) %}\n\n            {% for preview in previewMedia %}\n                {% set product = products|filter(product => product.cover.mediaId == preview.mediaId)|first %}\n\n                {% if product %}\n                    {% do product.cover.assign({\'media\': preview.preview}) %}\n                {% endif %}\n            {% endfor %}\n        {% endif %}\n    {% endfor %}\n{% endfor %}\n',	'include',	'include/cms-element-cross-selling.twig',	1,	UNHEX('019BBB6B4D3F7373A6848623014E0859'),	'2026-01-14 07:32:11.415',	'2026-01-14 07:32:11.941'),
(UNHEX('019BBB6B521570B996B309E7FEDFCB9D'),	'{% import \'include/spatial-preview-repository.twig\' as spatialPreviewRepository %}\n\n{#CMS Element - Image gallery and buy box #}\n{% set imageGallerySlots = page.cmsPage.sections.blocks.slots|filter(slot => slot.type == \'image-gallery\') %}\n\n{% for imageGallerySlot in imageGallerySlots %}\n    {% set sliderItems = imageGallerySlot.data.sliderItems %}\n\n    {% if sliderItems|length > 0 %}\n        {% set mediaIds = sliderItems|map(sliderItem => sliderItem.media.id) %}\n        {% set previewMedia = spatialPreviewRepository.getPreviewFromMedia(mediaIds) %}\n\n        {% for preview in previewMedia %}\n            {% set sliderItem = sliderItems|filter(item => item.media.id == preview.mediaId)|first %}\n\n            {% if sliderItem %}\n                {% do sliderItem.media.addExtension(\'preview\', preview.preview) %}\n            {% endif %}\n        {% endfor %}\n    {% endif %}\n{% endfor %}\n',	'include',	'include/cms-element-image-gallery.twig',	1,	UNHEX('019BBB6B4D3F7373A6848623014E0859'),	'2026-01-14 07:32:11.415',	'2026-01-14 07:32:11.941'),
(UNHEX('019BBB6B521570B996B309E7FF301293'),	'// Resources/scripts/include/spatial-preview-repository.twig\n{% macro getPreviewFromMedia(mediaIds) %}\n    {% set mediaIds = mediaIds|filter(v => v is not null) %}\n\n    {% if mediaIds is empty %}\n        {% return [] %}\n    {% endif %}\n\n    {% set criteria = {\n        \'associations\': {\n            \'preview\': {\n                \'associations\': {\n                    \'thumbnails\': {}\n                }\n            }\n        },\n        \'filter\': [{\n            \'type\': \'equalsAny\',\n            \'field\': \'mediaId\',\n            \'value\':  mediaIds\n        }]\n    } %}\n\n    {% return services.repository.search(\'ce_spatial_preview\', criteria) %}\n{% endmacro %}\n',	'include',	'include/spatial-preview-repository.twig',	1,	UNHEX('019BBB6B4D3F7373A6848623014E0859'),	'2026-01-14 07:32:11.415',	'2026-01-14 07:32:11.941'),
(UNHEX('019BBB6B521570B996B309E7FF31274D'),	'{% import \'include/spatial-preview-repository.twig\' as spatialPreviewRepository %}\n\n{# CMS Element - Three columns, product boxes #}\n{% set productBoxSlots = page.cmsPage.sections.blocks.slots|filter(slot => slot.type == \'product-box\') %}\n\n{% for productBoxSlot in productBoxSlots %}\n    {% set product = productBoxSlot.data.product %}\n\n    {% if product %}\n        {% set previewMedia = spatialPreviewRepository.getPreviewFromMedia([product.cover.mediaId])|first %}\n\n        {% if previewMedia %}\n            {% do product.cover.assign({\'media\': previewMedia.preview}) %}\n        {% endif %}\n    {% endif %}\n{% endfor %}\n',	'include',	'include/cms-element-product-box.twig',	1,	UNHEX('019BBB6B4D3F7373A6848623014E0859'),	'2026-01-14 07:32:11.415',	'2026-01-14 07:32:11.941'),
(UNHEX('019BBB6B521570B996B309E7FF81DA52'),	'// Resources/scripts/checkout-cart-page-loaded/checkout-cart-page-loaded.twig\n{% import \'include/spatial-preview-repository.twig\' as spatialPreviewRepository %}\n\n{% set page = hook.page %}\n{# @var page \\Shopware\\Storefront\\Page\\Checkout\\Offcanvas\\OffcanvasCartPage #}\n\n{% set permissionGranted = services.acl.can(\'ce_spatial_preview:read\') %}\n{% set lineItems = page.cart.lineItems %}\n\n{% if permissionGranted and lineItems|length > 0 %}\n    {% set coverIds = lineItems|map(item => item.cover.id) %}\n    {% set previewMedia = spatialPreviewRepository.getPreviewFromMedia(coverIds) %}\n\n    {% for preview in previewMedia %}\n        {% set lineItem = lineItems|filter(item => item.cover.id == preview.mediaId)|first %}\n\n        {% if lineItem %}\n            {% do lineItem.assign({\'cover\': preview.preview}) %}\n        {% endif %}\n    {% endfor %}\n{% endif %}\n',	'checkout-offcanvas-widget-loaded',	'checkout-offcanvas-widget-loaded/checkout-offcanvas-widget-loaded.twig',	1,	UNHEX('019BBB6B4D3F7373A6848623014E0859'),	'2026-01-14 07:32:11.415',	'2026-01-14 07:32:11.941'),
(UNHEX('019BBB6B521570B996B309E8005DD8C3'),	'// Resources/scripts/checkout-finish-page-loaded/checkout-finish-page-loaded.twig\n{% import \'include/spatial-preview-repository.twig\' as spatialPreviewRepository %}\n\n{% set page = hook.page %}\n{# @var page \\Shopware\\Storefront\\Page\\Checkout\\Confirm\\CheckoutFinishPage #}\n\n{% set permissionGranted = services.acl.can(\'ce_spatial_preview:read\') %}\n{% set lineItems = page.order.lineItems %}\n\n{% if permissionGranted and lineItems|length > 0 %}\n    {% set coverIds = lineItems|map(item => item.cover.id) %}\n    {% set previewMedia = spatialPreviewRepository.getPreviewFromMedia(coverIds) %}\n\n    {% for preview in previewMedia %}\n        {% set lineItem = lineItems|filter(item => item.cover.id == preview.mediaId)|first %}\n\n        {% if lineItem %}\n            {% do lineItem.assign({\'cover\': preview.preview}) %}\n        {% endif %}\n    {% endfor %}\n{% endif %}\n',	'checkout-finish-page-loaded',	'checkout-finish-page-loaded/checkout-finish-page-loaded.twig',	1,	UNHEX('019BBB6B4D3F7373A6848623014E0859'),	'2026-01-14 07:32:11.415',	'2026-01-14 07:32:11.941'),
(UNHEX('019BBB6B521570B996B309E8012E2ADB'),	'// Resources/scripts/navigation-page-loaded/navigation-page-loaded.twig\n{% set page = hook.page %}\n{# @var page \\Shopware\\Storefront\\Page\\Navigation\\NavigationPage #}\n\n{% set permissionGranted = services.acl.can(\'ce_spatial_preview:read\') %}\n\n{% if permissionGranted %}\n    {% include \'include/cms-element-cross-selling.twig\' %}\n    {% include \'include/cms-element-image-gallery.twig\' %}\n    {% include \'include/cms-element-product-box.twig\' %}\n    {% include \'include/cms-element-product-listing.twig\' %}\n    {% include \'include/cms-element-product-slider.twig\' %}\n    {% include \'include/cms-element-spatial-viewer.twig\' %}\n{% endif %}\n',	'navigation-page-loaded',	'navigation-page-loaded/navigation-page-loaded.twig',	1,	UNHEX('019BBB6B4D3F7373A6848623014E0859'),	'2026-01-14 07:32:11.415',	'2026-01-14 07:32:11.941'),
(UNHEX('019BBB6B521570B996B309E801C02240'),	'// Resources/scripts/product-page-loaded/product-loaded-script.twig\n{% set page = hook.page %}\n{# @var page \\Shopware\\Storefront\\Page\\Product\\ProductPage #}\n\n{% set permissionGranted = services.acl.can(\'ce_spatial_preview:read\') %}\n\n{% if permissionGranted %}\n    {% include \'include/cms-element-cross-selling.twig\' %}\n    {% include \'include/cms-element-image-gallery.twig\' %}\n    {% include \'include/cms-element-product-box.twig\' %}\n    {% include \'include/cms-element-product-listing.twig\' %}\n    {% include \'include/cms-element-product-slider.twig\' %}\n    {% include \'include/cms-element-spatial-viewer.twig\' %}\n{% endif %}\n',	'product-page-loaded',	'product-page-loaded/product-loaded-script.twig',	1,	UNHEX('019BBB6B4D3F7373A6848623014E0859'),	'2026-01-14 07:32:11.415',	'2026-01-14 07:32:11.942'),
(UNHEX('019BBB6B521570B996B309E8029517AC'),	'// Resources/scripts/checkout-confirm-page-loaded/checkout-confirm-page-loaded.twig\n{% import \'include/spatial-preview-repository.twig\' as spatialPreviewRepository %}\n\n{% set page = hook.page %}\n{# @var page \\Shopware\\Storefront\\Page\\Checkout\\Confirm\\CheckoutConfirmPage #}\n\n{% set permissionGranted = services.acl.can(\'ce_spatial_preview:read\') %}\n{% set lineItems = page.cart.lineItems %}\n\n{% if permissionGranted and lineItems|length > 0 %}\n    {% set coverIds = lineItems|map(item => item.cover.id) %}\n    {% set previewMedia = spatialPreviewRepository.getPreviewFromMedia(coverIds) %}\n\n    {% for preview in previewMedia %}\n        {% set lineItem = lineItems|filter(item => item.cover.id == preview.mediaId)|first %}\n\n        {% if lineItem %}\n            {% do lineItem.assign({\'cover\': preview.preview}) %}\n        {% endif %}\n    {% endfor %}\n{% endif %}\n',	'checkout-confirm-page-loaded',	'checkout-confirm-page-loaded/checkout-confirm-page-loaded.twig',	1,	UNHEX('019BBB6B4D3F7373A6848623014E0859'),	'2026-01-14 07:32:11.415',	'2026-01-14 07:32:11.942');

DROP TABLE IF EXISTS `seo_url`;
CREATE TABLE `seo_url` (
  `id` binary(16) NOT NULL,
  `language_id` binary(16) NOT NULL,
  `sales_channel_id` binary(16) DEFAULT NULL,
  `foreign_key` binary(16) NOT NULL,
  `route_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `path_info` varchar(750) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `seo_path_info` varchar(750) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `is_canonical` tinyint(1) DEFAULT NULL,
  `is_modified` tinyint(1) NOT NULL DEFAULT '0',
  `is_deleted` tinyint(1) NOT NULL DEFAULT '0',
  `custom_fields` json DEFAULT NULL,
  `created_at` datetime(3) NOT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq.seo_url.seo_path_info` (`language_id`,`sales_channel_id`,`seo_path_info`),
  UNIQUE KEY `uniq.seo_url.foreign_key` (`language_id`,`sales_channel_id`,`foreign_key`,`route_name`,`is_canonical`),
  KEY `fk.seo_url.sales_channel_id` (`sales_channel_id`),
  KEY `idx.foreign_key` (`language_id`,`foreign_key`,`sales_channel_id`,`is_canonical`),
  KEY `idx.path_info` (`language_id`,`sales_channel_id`,`is_canonical`,`path_info`),
  KEY `idx.delete_query` (`foreign_key`,`sales_channel_id`),
  CONSTRAINT `fk.seo_url.language_id` FOREIGN KEY (`language_id`) REFERENCES `language` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk.seo_url.sales_channel_id` FOREIGN KEY (`sales_channel_id`) REFERENCES `sales_channel` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `json.seo_url.custom_fields` CHECK (json_valid(`custom_fields`))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `seo_url_template`;
CREATE TABLE `seo_url_template` (
  `id` binary(16) NOT NULL,
  `sales_channel_id` binary(16) DEFAULT NULL,
  `route_name` varchar(255) NOT NULL,
  `entity_name` varchar(64) NOT NULL,
  `template` varchar(750) DEFAULT NULL,
  `is_valid` tinyint(1) NOT NULL DEFAULT '1',
  `custom_fields` json DEFAULT NULL,
  `created_at` datetime(3) NOT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq.seo_url_template.route_name` (`sales_channel_id`,`route_name`),
  CONSTRAINT `fk.seo_url_template.sales_channel_id` FOREIGN KEY (`sales_channel_id`) REFERENCES `sales_channel` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `json.seo_url_template.custom_fields` CHECK (json_valid(`custom_fields`))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

